import sys, json
from typing import List

class Solution:
    def shortestPathLength(self, graph: List[List[int]]) -> int:
        n = len(graph)
        if n <= 1:
            return 0
        full = (1 << n) - 1
        from collections import deque
        q = deque()
        seen = [[False] * n for _ in range(1 << n)]
        for i in range(n):
            q.append((1 << i, i, 0))
            seen[1 << i][i] = True
        while q:
            mask, u, d = q.popleft()
            for v in graph[u]:
                nm = mask | (1 << v)
                if nm == full:
                    return d + 1
                if not seen[nm][v]:
                    seen[nm][v] = True
                    q.append((nm, v, d + 1))
        return 0

