int shortestPathLength(int** graph, int graphSize, int* graphColSize) {
    int n = graphSize;
    if (n <= 1) return 0;
    int states = 1 << n;
    bool* seen = (bool*)calloc(states * n, sizeof(bool));
    int capacity = states * n;
    int* qMask = (int*)malloc(capacity * sizeof(int));
    int* qNode = (int*)malloc(capacity * sizeof(int));
    int* qDist = (int*)malloc(capacity * sizeof(int));
    int head = 0, tail = 0;
    int full = states - 1;
    for (int i = 0; i < n; ++i) {
        int mask = 1 << i;
        seen[mask * n + i] = true;
        qMask[tail] = mask; qNode[tail] = i; qDist[tail] = 0; tail++;
    }
    while (head < tail) {
        int mask = qMask[head], u = qNode[head], d = qDist[head++];
        for (int j = 0; j < graphColSize[u]; ++j) {
