            int nm = mask | (1 << v);
            if (nm == full) {
                free(seen); free(qMask); free(qNode); free(qDist);
                return d + 1;
            }
            int idx = nm * n + v;
            if (!seen[idx]) {
                seen[idx] = true;
                qMask[tail] = nm; qNode[tail] = v; qDist[tail] = d + 1; tail++;
            }
        }
