class Solution {
    public int shortestPathLength(int[][] graph) {
        int n = graph.length;
        if (n <= 1) return 0;
        int full = (1 << n) - 1;
        boolean[][] seen = new boolean[1 << n][n];
        ArrayDeque<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            q.add(new int[]{1 << i, i, 0});
            seen[1 << i][i] = true;
        }
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int mask = cur[0], u = cur[1], d = cur[2];
            for (int v : graph[u]) {
                int nm = mask | (1 << v);
                if (nm == full) return d + 1;
                if (!seen[nm][v]) {
                    seen[nm][v] = true;
                    q.add(new int[]{nm, v, d + 1});
                }
            }
        }
        return 0;
    }
}

